public class CircularQueue {
    int[] arr; int front=0, rear=0, size=0, cap;
    CircularQueue(int k) { arr = new int[k]; cap = k; }
    boolean enQueue(int val) {
        if (size == cap) return false;
        arr[rear] = val;
        rear = (rear + 1) % cap;
        size++;
        return true;
    }
    int deQueue() {
        if (size == 0) return -1;
        int val = arr[front];
        front = (front + 1) % cap;
        size--;
        return val;
    }
    int Front() { return size == 0 ? -1 : arr[front]; }
    boolean isEmpty() { return size == 0; }
    boolean isFull()  { return size == cap; }
}

